liveRenderer.source:
{%- comment -%} LX-FR-0911: französische Ausgabe durch Ersetzen eingefangener Wortgruppen (dropship/fr-produkte-0911/vorlage_fr), deutscher Zweig unverändert {%- endcomment -%}{%- capture lx_fr_lux_spezifikationen -%}{%- assign g = product.metafields['mm-google-shopping'] -%}
{%- assign v = product.selected_or_first_available_variant -%}
{%- assign vend = product.vendor | downcase -%}
{%- assign zeilen = 0 -%}
{%- comment -%} Faktenlisten aus dem Beschreibungstext (siehe lux_beschreibung) einsammeln {%- endcomment -%}
{%- assign d = product.description -%}
{%- assign listen = '' -%}
{%- if d contains '<h4>Details</h4>' -%}
  {%- assign listen = d | split: '<h4>Details</h4>' | last | split: '</ul>' | first -%}
{%- endif -%}
{%- assign klassen = 'ls-produktdetails,ls-feed-details,gmc-details' | split: ',' -%}
{%- for cls in klassen -%}
  {%- assign marker = '<div class="' | append: cls | append: '">' -%}
  {%- if d contains marker -%}
    {%- assign inner = d | split: marker | last | split: '</div>' | first -%}
    {%- assign listen = listen | append: inner -%}
  {%- endif -%}
{%- endfor -%}
{%- assign optnames = '' -%}
{%- for option in product.options_with_values -%}{%- assign on = option.name | downcase -%}{%- assign optnames = optnames | append: '|' | append: on -%}{%- endfor -%}
{%- assign hat_marke = false -%}{%- assign hat_material = false -%}{%- assign hat_gewicht = false -%}{%- assign gesehen = '|' -%}
{%- capture detailrows -%}
{%- if listen != '' -%}
  {%- assign items = listen | split: '<li>' -%}
  {%- for it in items -%}
    {%- if it contains '</strong>' -%}
      {%- assign key = it | split: '</strong>' | first | strip_html | remove: ':' | strip -%}
      {%- assign val = it | split: '</strong>' | last | split: '</li>' | first | strip_html | strip -%}
      {%- assign kdc = key | downcase -%}
      {%- comment -%} 05.09.2026: Schluessel normalisieren, damit «Grössen/Grösse», «Muster/Design», «Farben/Farbe» nur EINMAL erscheinen (Audit produktseite). {%- endcomment -%}
      {%- assign kn = kdc | replace: 'größe', 'grösse' | replace: 'grössen', 'grösse' | replace: 'farben', 'farbe' | replace: 'design', 'muster' | replace: 'materialien', 'material' | strip -%}
      {%- assign kn_pipe = '|' | append: kn | append: '|' -%}
      {%- if gesehen contains kn_pipe -%}{%- assign val = '' -%}{%- else -%}{%- assign gesehen = gesehen | append: kn_pipe -%}{%- endif -%}
      {%- if val != '' and key != '' and kdc != 'versand' and kdc != 'lieferzeit' and kdc != 'lieferung' -%}
        {%- unless optnames contains kdc -%}
          {%- if kdc == 'marke' -%}{%- assign hat_marke = true -%}{%- endif -%}
          {%- if kdc == 'material' -%}{%- assign hat_material = true -%}{%- endif -%}
          {%- if kdc == 'gewicht' -%}{%- assign hat_gewicht = true -%}{%- endif -%}
          <tr><th>{{ key }}</th><td>{{ val }}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}
        {%- endunless -%}
      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
{%- endcapture -%}
{%- capture rows -%}
{%- if product.type != blank -%}<tr><th>Kategorie</th><td>{{ product.type }}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}
{%- unless hat_marke or vend == blank or vend contains 'luxestyle' or vend contains 'cj' or vend contains 'fortura' or vend contains 'bigbuy' or vend contains 'aban' -%}<tr><th>Marke</th><td>{{ product.vendor }}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endunless -%}
{{ detailrows }}
{%- for option in product.options_with_values -%}
{%- if option.name != 'Title' -%}<tr><th>{{ option.name }}</th><td>{%- for val in option.values limit: 14 -%}{{ val }}{%- unless forloop.last %}, {% endunless -%}{%- endfor -%}{%- if option.values.size > 14 %} … (+{{ option.values.size | minus: 14 }} weitere){%- endif -%}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}
{%- endfor -%}
{%- assign hat_groesse = false -%}{%- if optnames contains 'grösse' or optnames contains 'größe' or optnames contains 'size' or detailrows contains '<th>Grösse</th>' or detailrows contains '<th>Masse</th>' -%}{%- assign hat_groesse = true -%}{%- endif -%}
{%- if hat_groesse == false and product.title contains ' cm' -%}{%- assign tcm = product.title | split: ' cm' | first | split: ' ' | last | strip -%}{%- assign tnum = tcm | plus: 0 -%}{%- if tnum > 0 -%}<tr><th>Masse</th><td>{{ tcm }} cm</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}{%- endif -%}
{%- if g.material and hat_material == false -%}<tr><th>Material</th><td>{{ g.material.value }}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}
{%- if v.weight > 0 and hat_gewicht == false -%}<tr><th>Gewicht</th><td>{{ v.weight | weight_with_unit: v.weight_unit }}</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}
{%- if g.condition -%}{%- if g.condition.value == 'new' -%}<tr><th>Zustand</th><td>Neu</td></tr>{%- assign zeilen = zeilen | plus: 1 -%}{%- endif -%}{%- endif -%}
{%- endcapture -%}
{%- if zeilen > 0 -%}
<div id="lux-spezi" style="margin:20px 0 6px;">
<h3 style="font-size:1.05rem;font-weight:600;margin:0 0 8px;">Spezifikationen &amp; Details</h3>
<table style="width:100%;border-collapse:collapse;font-size:.92rem;line-height:1.5">{{ rows }}</table>
<style>#lux-spezi th{width:38%;min-width:110px;text-align:left;font-weight:500;color:#666;vertical-align:top}#lux-spezi th,#lux-spezi td{padding:7px 8px;border-bottom:1px solid #ececec}#lux-spezi tr:nth-child(odd){background:#fafafa}</style>
</div>
{%- endif -%}{%- endcapture -%}{%- if request.locale.iso_code == 'fr' -%}{{ lx_fr_lux_spezifikationen | replace: '<tr><th>Kategorie</th>', '<tr><th>Catégorie</th>' | replace: '<tr><th>Marke</th>', '<tr><th>Marque</th>' | replace: '<tr><th>Masse</th>', '<tr><th>Dimensions</th>' | replace: '<tr><th>Material</th>', '<tr><th>Matière</th>' | replace: '<tr><th>Gewicht</th>', '<tr><th>Poids</th>' | replace: '<tr><th>Zustand</th><td>Neu</td>', '<tr><th>État</th><td>Neuf</td>' | replace: 'Spezifikationen &amp; Details', 'Caractéristiques et détails' }}{%- else -%}{{ lx_fr_lux_spezifikationen }}{%- endif -%}
